import { checkExceptions, createWaiter, WaiterState, } from "@smithy/core/client";
import { GetWebFunctionCommand, } from "../commands/GetWebFunctionCommand";
const checkState = async (client, input) => {
    let reason;
    try {
        let result = await client.send(new GetWebFunctionCommand(input));
        reason = result;
        try {
            const returnComparator = () => {
                return result.state;
            };
            if (returnComparator() === "Deleting") {
                return { state: WaiterState.RETRY, reason };
            }
        }
        catch (e) { }
    }
    catch (exception) {
        reason = exception;
        if (exception.name === "ResourceNotFoundException") {
            return { state: WaiterState.SUCCESS, reason };
        }
    }
    return { state: WaiterState.RETRY, reason };
};
export const waitForWebFunctionDeleted = async (params, input) => {
    const serviceDefaults = { minDelay: 1, maxDelay: 300 };
    return createWaiter({ ...serviceDefaults, ...params }, input, checkState);
};
export const waitUntilWebFunctionDeleted = async (params, input) => {
    const serviceDefaults = { minDelay: 1, maxDelay: 300 };
    const result = await createWaiter({ ...serviceDefaults, ...params }, input, checkState);
    return checkExceptions(result);
};
